 class IntroLayout extends LinearLayout {IntroLayout(Context c){super(c);}@Override protected void onMeasure(int widthSpec,int heightSpec){int available=MeasureSpec.getSize(heightSpec),width=MeasureSpec.getSize(widthSpec);for(int step=0;step<=8;step++){int natural=0;for(int i=0;i<getChildCount();i++){View child=getChildAt(i);if(child instanceof RadarPanel){child.getLayoutParams().height=Math.max(dp(64),(int)(available*(.30-step*.025)));}else if(child instanceof TextView){TextView text=(TextView)child;float size="intro-title".equals(text.getTag())?30-step*.75f:i==1?11:17-step*.5f;text.setTextSize(size);int pad=dp(Math.max(2,6-step*.5f));text.setPadding(0,pad,0,pad);}int childHeight=child.getLayoutParams().height;child.measure(MeasureSpec.makeMeasureSpec(width,MeasureSpec.EXACTLY),childHeight>0?MeasureSpec.makeMeasureSpec(childHeight,MeasureSpec.EXACTLY):MeasureSpec.makeMeasureSpec(0,MeasureSpec.UNSPECIFIED));natural+=child.getMeasuredHeight();}if(natural<=available)break;}super.onMeasure(widthSpec,heightSpec);}}
