 LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);TextView title=text(t.title+"  ›",17,TEXT);title.setMinHeight(dp(48));title.setGravity(Gravity.CENTER_VERTICAL);title.setFocusable(true);title.setContentDescription("Описание подгруппы: "+t.title);title.setOnClickListener(v->show("topic:"+t.id));header.addView(title,new LinearLayout.LayoutParams(0,-2,1));Switch sw=new Switch(this);sw.setText("");sw.setPadding(dp(6),dp(10),dp(6),dp(10));sw.setMinHeight(dp(48));header.addView(sw,new LinearLayout.LayoutParams(-2,-2));if(!t.id.contains(".")&&Inbox.unreadFor(this,t.id)>0){TextView unread=text("● "+Inbox.unreadFor(this,t.id),13,Color.rgb(247,62,88));unread.setMinHeight(dp(48));unread.setMinWidth(dp(48));unread.setGravity(Gravity.CENTER);unread.setContentDescription("Открыть уведомления: "+t.title);unread.setOnClickListener(v->openCategoryNotices(t.id));header.addView(unread);}c.addView(header);
 int total=Catalog.leaves(t.id).size();TextView status=text("",12,MUTED);if(!t.leaf())c.addView(status);
 Runnable update=()->{int n=Store.count(Store.selected(this),t.id);sw.setChecked(n>0);sw.setContentDescription(t.title+", выбрано "+n+" из "+total);status.setText(n+" из "+total+" включено");};refreshingRows=true;update.run();refreshingRows=false;selectionRefreshers.add(update);
 sw.setOnCheckedChangeListener((button,on)->{if(refreshingRows)return;Store.toggle(this,t.id,on);refreshingRows=true;for(Runnable refresh:selectionRefreshers)refresh.run();refreshingRows=false;refreshBranch();});
 if(!t.leaf()){Button expand=button("› "+(t.children.size()+(t.id.equals("consumer")?1:0)),()->{});expand.setTextSize(17);expand.setTextColor(CYAN);expand.setPadding(0,0,0,0);expand.setMinWidth(0);expand.setMinimumWidth(0);expand.setElevation(dp(2));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(56),dp(48));lp.setMargins(dp(8),0,0,0);header.addView(expand,lp);
 LinearLayout children=new LinearLayout(this);children.setOrientation(LinearLayout.VERTICAL);children.setVisibility(View.GONE);c.addView(children);expand.setContentDescription("Раскрыть "+t.title+", подразделов: "+(t.children.size()+(t.id.equals("consumer")?1:0)));expand.setOnClickListener(v->{boolean opening=children.getVisibility()!=View.VISIBLE;if(opening&&children.getChildCount()==0){if(t.id.equals("consumer"))BasketScreen.entry(this,children);for(Catalog.Topic child:t.children)topicRow(child,children);}android.transition.AutoTransition transition=new android.transition.AutoTransition();transition.setDuration(180);android.transition.TransitionManager.beginDelayedTransition(body,transition);children.setVisibility(opening?View.VISIBLE:View.GONE);expand.setText((opening?"⌄ ":"› ")+(t.children.size()+(t.id.equals("consumer")?1:0)));expand.setContentDescription((opening?"Свернуть ":"Раскрыть ")+t.title+", подразделов: "+(t.children.size()+(t.id.equals("consumer")?1:0)));});}
